SELECT id, user_id, status, last_error, ttl_expires_at, started_at, updated_at, completed_at, ext::text AS ext, COALESCE( CASE WHEN (snapshot_json #>> '{observability,summary,totalDurationMs}') ~ '^[0-9]+$' THEN (snapshot_json #>> '{observability,summary,totalDurationMs}')::bigint END, CASE WHEN (snapshot_json #>> '{observability,summary,total_duration_ms}') ~ '^[0-9]+$' THEN (snapshot_json #>> '{observability,summary,total_duration_ms}')::bigint END, 0 ) AS duration_ms, COALESCE( CASE WHEN (snapshot_json #>> '{observability,summary,totalTokens}') ~ '^[0-9]+$' THEN (snapshot_json #>> '{observability,summary,totalTokens}')::int END, CASE WHEN (snapshot_json #>> '{observability,summary,total_tokens}') ~ '^[0-9]+$' THEN (snapshot_json #>> '{observability,summary,total_tokens}')::int END, 0 ) AS total_tokens, COALESCE( CASE WHEN (snapshot_json #>> '{observability,summary,toolCalls}') ~ '^[0-9]+$' THEN (snapshot_json #>> '{observability,summary,toolCalls}')::int END, CASE WHEN (snapshot_json #>> '{observability,summary,tool_calls}') ~ '^[0-9]+$' THEN (snapshot_json #>> '{observability,summary,tool_calls}')::int END, 0 ) AS tool_calls FROM alphafrog_agent_run WHERE user_id = #{userId}
AND status = #{status}
AND started_at >= #{fromTime}
ORDER BY started_at DESC LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(1)
FROM alphafrog_agent_run
WHERE user_id = #{userId}

    AND status = #{status}


    AND started_at >= #{fromTime}

SELECT id, user_id, status, current_step, max_steps, plan_json::text AS plan_json, snapshot_json::text AS snapshot_json, last_error, ttl_expires_at, started_at, updated_at, completed_at, ext::text AS ext, tool_job_anchor_json::text AS tool_job_anchor_json, 0 AS duration_ms, 0 AS total_tokens, 0 AS tool_calls FROM alphafrog_agent_run WHERE status IN
CAST(#{s} AS VARCHAR)
AND updated_at > #{fromTime} ORDER BY updated_at ASC LIMIT #{limit}

SELECT id, user_id, status, current_step, max_steps, plan_json::text AS plan_json, snapshot_json::text AS snapshot_json, last_error, ttl_expires_at, started_at, updated_at, completed_at, ext::text AS ext, tool_job_anchor_json::text AS tool_job_anchor_json, 0 AS duration_ms, 0 AS total_tokens, 0 AS tool_calls FROM alphafrog_agent_run WHERE status IN
CAST(#{s} AS VARCHAR)
AND (updated_at > #{cursorTime} OR (updated_at = #{cursorTime} AND id > #{cursorRunId})) ORDER BY updated_at ASC, id ASC LIMIT #{limit}

