UPDATE alphafrog_agent_run
SET tool_job_anchor_json = CAST(#{toolJobAnchorJson} AS jsonb),
    updated_at = CURRENT_TIMESTAMP
WHERE id = #{id}
  AND status = #{expectedStatus}

UPDATE alphafrog_agent_run
SET tool_job_anchor_json = CAST(#{toolJobAnchorJson} AS jsonb),
    status = #{newStatus},
    updated_at = CURRENT_TIMESTAMP
WHERE id = #{id}
  AND status = #{expectedStatus}

UPDATE alphafrog_agent_run
SET tool_job_anchor_json = CAST(#{toolJobAnchorJson} AS jsonb),
    updated_at = CURRENT_TIMESTAMP
WHERE id = #{id}
  AND status = #{expectedStatus}
  AND (tool_job_anchor_json IS NULL OR tool_job_anchor_json = '{}'::jsonb)

UPDATE alphafrog_agent_run
SET tool_job_anchor_json = CAST(#{toolJobAnchorJson} AS jsonb),
    updated_at = CURRENT_TIMESTAMP
WHERE id = #{id}
  AND status = 'EXECUTING'
  AND tool_job_anchor_json #>> '{resumeState}' = 'LAUNCHING'
  AND COALESCE((tool_job_anchor_json #>> '{resultConsumed}')::boolean, false)
  AND tool_job_anchor_json #>> '{resumeToken}' = #{expectedResumeToken}
  AND (tool_job_anchor_json #>> '{resumeLeaseVersion}')::bigint = #{expectedLeaseVersion}

UPDATE alphafrog_agent_run
SET tool_job_anchor_json = CAST(#{toolJobAnchorJson} AS jsonb),
    updated_at = CURRENT_TIMESTAMP
WHERE id = #{id}
  AND status = #{expectedStatus}
  AND tool_job_anchor_json ->> 'operationId' = #{expectedOperationId}

UPDATE alphafrog_agent_run
SET tool_job_anchor_json = CAST(#{toolJobAnchorJson} AS jsonb),
    updated_at = CURRENT_TIMESTAMP
WHERE id = #{id}
  AND status = #{expectedStatus}
  AND tool_job_anchor_json ->> 'operationId' = #{expectedOperationId}
  AND tool_job_anchor_json ->> 'runDisposition' = 'DAG_BLOCKING_NO_RESUME'
  AND COALESCE((tool_job_anchor_json ->> 'autoResume')::boolean, true) = false
  AND tool_job_anchor_json ->> 'blockingOwnerId' = #{expectedOwnerId}
  AND tool_job_anchor_json ->> 'blockingLeaseUntil' = #{expectedLeaseUntil}
  AND CAST(tool_job_anchor_json ->> 'blockingLeaseUntil' AS timestamptz)
      > CURRENT_TIMESTAMP

UPDATE alphafrog_agent_run
SET tool_job_anchor_json = CAST(#{toolJobAnchorJson} AS jsonb),
    updated_at = CURRENT_TIMESTAMP
WHERE id = #{id}
  AND status = #{expectedStatus}
  AND tool_job_anchor_json ->> 'operationId' = #{expectedOperationId}
  AND tool_job_anchor_json ->> 'anchorState' = 'PREPARING'
  AND tool_job_anchor_json ->> 'runDisposition' = 'DAG_BLOCKING_NO_RESUME'
  AND COALESCE((tool_job_anchor_json ->> 'autoResume')::boolean, true) = false
  AND tool_job_anchor_json ->> 'blockingOwnerId' = #{expectedOwnerId}
  AND tool_job_anchor_json ->> 'blockingLeaseUntil' = #{expectedLeaseUntil}
  AND CAST(tool_job_anchor_json ->> 'blockingLeaseUntil' AS timestamptz)
      > CURRENT_TIMESTAMP

UPDATE alphafrog_agent_run
SET tool_job_anchor_json = CAST(#{toolJobAnchorJson} AS jsonb),
    updated_at = CURRENT_TIMESTAMP
WHERE id = #{id}
  AND status IN ('EXECUTING', 'FAILED', 'CANCELED')
  AND tool_job_anchor_json ->> 'operationId' = #{expectedOperationId}
  AND tool_job_anchor_json ->> 'runDisposition' = 'DAG_BLOCKING_PREPARING_ABORT'
  AND COALESCE((tool_job_anchor_json ->> 'autoResume')::boolean, true) = false
  AND tool_job_anchor_json ->> 'blockingOwnerId' = #{expectedOwnerId}
  AND tool_job_anchor_json ->> 'blockingLeaseUntil' = #{expectedLeaseUntil}
  AND (
        (tool_job_anchor_json ->> 'reservationJson')::jsonb
            ->> 'state'
      ) = 'RELEASED'
  AND (
        (
            tool_job_anchor_json ->> 'anchorState' = 'ABORTING'
            AND CAST(#{toolJobAnchorJson} AS jsonb)
                ->> 'cleanupSourceOwnerId' = #{expectedOwnerId}
            AND CAST(#{toolJobAnchorJson} AS jsonb)
                ->> 'cleanupSourceLeaseUntil' = #{expectedLeaseUntil}
        )
        OR (
            tool_job_anchor_json ->> 'anchorState' = 'CLEARING'
            AND (
                tool_job_anchor_json ->> 'blockingLeaseUntil'
            )::timestamptz <= CURRENT_TIMESTAMP
            AND CAST(#{toolJobAnchorJson} AS jsonb)
                ->> 'cleanupSourceOwnerId'
                = tool_job_anchor_json ->> 'cleanupSourceOwnerId'
            AND CAST(#{toolJobAnchorJson} AS jsonb)
                ->> 'cleanupSourceLeaseUntil'
                = tool_job_anchor_json ->> 'cleanupSourceLeaseUntil'
        )
      )

UPDATE alphafrog_agent_run
SET tool_job_anchor_json = CAST('{}' AS jsonb),
    updated_at = CURRENT_TIMESTAMP
WHERE id = #{id}
  AND status IN ('EXECUTING', 'FAILED', 'CANCELED')
  AND tool_job_anchor_json ->> 'operationId' = #{expectedOperationId}
  AND tool_job_anchor_json ->> 'anchorState' = 'CLEARING'
  AND tool_job_anchor_json ->> 'runDisposition' = 'DAG_BLOCKING_PREPARING_ABORT'
  AND COALESCE((tool_job_anchor_json ->> 'autoResume')::boolean, true) = false
  AND tool_job_anchor_json ->> 'blockingOwnerId' = #{expectedOwnerId}
  AND tool_job_anchor_json ->> 'blockingLeaseUntil' = #{expectedLeaseUntil}
  AND (
        (tool_job_anchor_json ->> 'reservationJson')::jsonb
            ->> 'state'
      ) = 'RELEASED'

UPDATE alphafrog_agent_run
SET tool_job_anchor_json = CAST(#{toolJobAnchorJson} AS jsonb),
    status = #{newStatus},
    updated_at = CURRENT_TIMESTAMP
WHERE id = #{id}
  AND status = #{expectedStatus}
  AND tool_job_anchor_json ->> 'operationId' = #{expectedOperationId}

UPDATE alphafrog_agent_run
SET tool_job_anchor_json = CAST('{}' AS jsonb),
    updated_at = CURRENT_TIMESTAMP
WHERE id = #{id}
  AND status = #{expectedStatus}
  AND tool_job_anchor_json ->> 'operationId' = #{expectedOperationId}

UPDATE alphafrog_agent_run
SET tool_job_anchor_json = CAST(#{toolJobAnchorJson} AS jsonb),
    updated_at = CURRENT_TIMESTAMP
WHERE id = #{id}
  AND status IN ('EXECUTING', 'FAILED', 'CANCELED')
  AND tool_job_anchor_json ->> 'operationId' = #{expectedOperationId}
  AND tool_job_anchor_json ->> 'blockingOwnerId' = #{expectedOwnerId}
  AND tool_job_anchor_json ->> 'runDisposition' = 'DAG_BLOCKING_WORKER_LOST'
  AND COALESCE((tool_job_anchor_json ->> 'autoResume')::boolean, true) = false

UPDATE alphafrog_agent_run
SET tool_job_anchor_json = CAST('{}' AS jsonb),
    updated_at = CURRENT_TIMESTAMP
WHERE id = #{id}
  AND status = #{expectedStatus}
  AND tool_job_anchor_json ->> 'operationId' = #{expectedOperationId}
  AND tool_job_anchor_json ->> 'anchorState' = 'TERMINAL'
  AND COALESCE((tool_job_anchor_json ->> 'usagePersisted')::boolean, false)
  AND tool_job_anchor_json ->> 'reservationJson' IS NOT NULL
  AND CAST(tool_job_anchor_json ->> 'reservationJson' AS jsonb) ->> 'state' = 'RELEASED'

UPDATE alphafrog_agent_run
SET tool_job_anchor_json = tool_job_anchor_json || jsonb_build_object(
        'autoResume', false,
        'runDisposition', 'CHECKPOINT_FAILED',
        'finalizerError', #{finalizerError}
    ),
    updated_at = CURRENT_TIMESTAMP
WHERE id = #{id}
  AND status = 'WAITING_TOOL_JOB'
  AND tool_job_anchor_json IS NOT NULL
  AND tool_job_anchor_json <> '{}'::jsonb
  AND tool_job_anchor_json ->> 'operationId' = #{operationId}
  AND tool_job_anchor_json ->> 'toolCallId' = #{toolCallId}
  AND COALESCE((tool_job_anchor_json ->> 'attempt')::integer, 0) = #{attempt}
  AND tool_job_anchor_json ->> 'taskId' = #{taskId}
  AND COALESCE((tool_job_anchor_json ->> 'checkpointVersion')::integer, 0) = #{checkpointVersion}

UPDATE alphafrog_agent_run
SET last_error = #{marker},
    updated_at = CURRENT_TIMESTAMP
WHERE id = #{id}
  AND status = 'WAITING_TOOL_JOB'
  AND tool_job_anchor_json IS NOT NULL
  AND tool_job_anchor_json <> '{}'::jsonb
  AND tool_job_anchor_json ->> 'operationId' = #{operationId}
  AND tool_job_anchor_json ->> 'toolCallId' = #{toolCallId}
  AND COALESCE((tool_job_anchor_json ->> 'attempt')::integer, 0) = #{attempt}
  AND tool_job_anchor_json ->> 'taskId' = #{taskId}
  AND COALESCE((tool_job_anchor_json ->> 'checkpointVersion')::integer, 0) = #{checkpointVersion}
  AND (last_error IS NULL OR last_error = #{marker})

UPDATE alphafrog_agent_run
SET last_error = NULL,
    updated_at = CURRENT_TIMESTAMP
WHERE id = #{id}
  AND last_error = #{marker}

UPDATE alphafrog_agent_run
SET status = #{newStatus},
    updated_at = CURRENT_TIMESTAMP
WHERE id = #{id}
  AND status = #{expectedStatus}

UPDATE alphafrog_agent_run
SET tool_job_anchor_json = CAST(#{toolJobAnchorJson} AS jsonb),
    updated_at = CURRENT_TIMESTAMP
WHERE id = #{id}
  AND status = #{expectedStatus}
  AND tool_job_anchor_json #>> '{resumeState}' = #{expectedResumeState}
  AND tool_job_anchor_json #>> '{resumeToken}' = #{expectedResumeToken}
  AND (tool_job_anchor_json #>> '{resumeLeaseVersion}')::bigint = #{expectedLeaseVersion}

UPDATE alphafrog_agent_run
SET tool_job_anchor_json = CAST(#{toolJobAnchorJson} AS jsonb),
    status = #{newStatus},
    updated_at = CURRENT_TIMESTAMP
WHERE id = #{id}
  AND status = #{expectedStatus}
  AND tool_job_anchor_json #>> '{resumeState}' = #{expectedResumeState}
  AND tool_job_anchor_json #>> '{resumeToken}' = #{expectedResumeToken}
  AND (tool_job_anchor_json #>> '{resumeLeaseVersion}')::bigint = #{expectedLeaseVersion}

UPDATE alphafrog_agent_run
SET tool_job_anchor_json = CAST(#{toolJobAnchorJson} AS jsonb)
        || jsonb_build_object(
            'resumeLauncherOwnerId', #{launcherOwnerId}::text,
            'resumeClaimedAt', CURRENT_TIMESTAMP,
            'resumeLauncherLeaseUntil',
                CURRENT_TIMESTAMP + make_interval(secs => #{leaseSeconds})
        ),
    status = #{newStatus},
    updated_at = CURRENT_TIMESTAMP
WHERE id = #{id}
  AND status = #{expectedStatus}
  AND tool_job_anchor_json #>> '{resumeState}' = 'READY'
  AND NOT COALESCE((tool_job_anchor_json #>> '{resultConsumed}')::boolean, false)
  AND tool_job_anchor_json #>> '{resumeToken}' = #{expectedResumeToken}
  AND (tool_job_anchor_json #>> '{resumeLeaseVersion}')::bigint = #{expectedLeaseVersion}

UPDATE alphafrog_agent_run
SET tool_job_anchor_json = CAST('{}' AS jsonb),
    updated_at = CURRENT_TIMESTAMP
WHERE id = #{id}
  AND tool_job_anchor_json #>> '{resumeState}' IN ('LAUNCHING', 'ACCEPTED')
  AND COALESCE((tool_job_anchor_json #>> '{resultConsumed}')::boolean, false)
  AND tool_job_anchor_json #>> '{resumeToken}' = #{expectedResumeToken}
  AND (tool_job_anchor_json #>> '{resumeLeaseVersion}')::bigint = #{expectedLeaseVersion}
  AND tool_job_anchor_json #>> '{resumeLauncherOwnerId}' = #{expectedLauncherOwnerId}
  AND status IN ('COMPLETED', 'PARTIAL', 'FAILED', 'CANCELED', 'EXPIRED')

UPDATE alphafrog_agent_run
SET tool_job_anchor_json = CAST('{}' AS jsonb),
    updated_at = CURRENT_TIMESTAMP
WHERE id = #{id}
  AND tool_job_anchor_json #>> '{resumeState}' = #{expectedResumeState}
  AND tool_job_anchor_json #>> '{resumeToken}' = #{expectedToken}
  AND (tool_job_anchor_json #>> '{resumeLeaseVersion}')::bigint = #{expectedLeaseVersion}
